describe("Rog modifier value offers",function()
 local sim=require("Modules.CraftingSimulator");local rog=require("Modules.CraftingRog")
 local raw="Rarity: NORMAL\nIron Hat\nItem Level: 86"
 local function stream(values) local i=0;return function() i=i+1;return assert(values[i],"Unexpected random draw") end end
 before_each(function() newBuild();main.popups={} end)
 after_each(function() main.popups={} end)
 it("keeps the best normalized candidate on one side and preserves the other side",function()
  local model=sim.model(raw);local state=copyTable(model.initial);state.rarity="RARE";state.affixes={{id="IncreasedLife2",range=0.5},{id="FireResist2",range=0.25}}
  local before=copyTable(state);local action={method="rog_reroll",rogOperation="values_side",rogSide="Prefix",rogAttempts=3,artifactCost={grand=7}}
  local expected=sim.rollRange(model.byId.IncreasedLife2,function() return 0.9 end)
  local result=sim.action(model,state,action,stream({0.1,0.9,0.4}));assert.same(before,state)
  assert.equal(expected,result.affixes[1].range);assert.same(before.affixes[2],result.affixes[2]);sim.validateState(model,result)
  assert.matches("not always better",sim.actionWarnings(action,model)[1].message,1,true)
  assert.same({["Metadata/Items/Expedition/ExpeditionVendorCurrencyFaction3_3"]=7},sim.components(action))
  local odds=sim.calculate(raw,action,{},state,{trials=3,requirements={minAffixes=2}});assert.is_true(odds.sampled);assert.is_truthy(odds.warnings)
  local recipe=sim.simulate(raw,{steps={action},targets={},requirements={minAffixes=2}},{trials=2,maxActions=1,initialState=state,forceFirstAction=true});assert.equal(2,recipe.trials)
 end)
 it("selects one modifier once and retains that choice across attempts",function()
  local model=sim.model(raw);local state=copyTable(model.initial);state.rarity="RARE";state.affixes={{id="IncreasedLife2",range=0.5},{id="FireResist2",range=0.25}}
  local action={method="rog_reroll",rogOperation="values_one",rogAttempts=3};local result=sim.action(model,state,action,stream({0.9,0.1,0.9,0.4}))
  assert.same(state.affixes[1],result.affixes[1]);assert.equal(sim.rollRange(model.byId.FireResist2,function() return 0.9 end),result.affixes[2].range)
  assert.has_error(function() rog.validate({rogOperation="values_one",rogSide="Prefix",rogAttempts=3}) end)
  assert.has_error(function() rog.validate({rogOperation="values_side",rogSide="Prefix",rogAttempts=6}) end)
  local empty=copyTable(state);empty.affixes={};assert.matches("No modifiers",sim.configurationReason(model,empty,action),1,true)
 end)
 it("updates saved recipe offers without losing prices or routes",function()
  local recipe={steps={{method="rog_reroll",rogOperation="values_one",rogAttempts=3,artifactCost={grand=7},maxAttempts=4,untilRequirements={minAffixes=2},onFailureAction="stop"}},targets={},requirements={minAffixes=2}}
  local saved;local editor=require("Classes.CraftingRecipeControl").Open(recipe,{method="alchemy"},function(value) saved=value end,sim.model(raw))
  editor.editRog:Click();local popup=main.popups[1].controls;assert.equal("values_one",popup.operation:GetSelValueByKey("val"))
  popup.operation:SelByValue("values_side","val");popup.side:SelByValue("Suffix","val");popup.attempts:SelByValue(5,"val");popup.keep:Click();editor.keep:Click()
  assert.equal("values_side",saved.steps[1].rogOperation);assert.equal("Suffix",saved.steps[1].rogSide);assert.equal(5,saved.steps[1].rogAttempts)
  assert.equal(7,saved.steps[1].artifactCost.grand);assert.equal(4,saved.steps[1].maxAttempts);assert.equal("stop",saved.steps[1].onFailureAction)
 end)
 it("retains observed value offers in the editor and recipe state",function()
  local saved;local c=require("Classes.CraftingRogControl").Open(nil,function(value) saved=value end)
  c.operation:SelByValue("values_one","val");c.attempts:SelByValue(5,"val");assert.is_false(c.side:IsShown());assert.is_true(c.valueHint:IsShown());c.keep:Click()
  assert.equal("values_one",saved.rogOperation);assert.equal(5,saved.rogAttempts);assert.is_nil(saved.rogSide)
  local recipe=sim.validateRecipe({steps={saved},targets={},requirements={minAffixes=1}});assert.equal(5,recipe.steps[1].rogAttempts)
  c=require("Classes.CraftingRogControl").Open(saved,function() end);assert.equal("values_one",c.operation:GetSelValueByKey("val"));assert.equal(5,c.attempts:GetSelValueByKey("val"));main:ClosePopup()
 end)
end)
